PRAGMA foreign_keys=ON;
CREATE TABLE source(source_id TEXT PRIMARY KEY,producer TEXT NOT NULL,url TEXT NOT NULL,license TEXT NOT NULL,limits TEXT NOT NULL);
CREATE TABLE dataset_version(version_id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES source,label TEXT NOT NULL,retrieved_at TEXT NOT NULL,coverage TEXT NOT NULL);
CREATE TABLE raw_file(raw_id TEXT PRIMARY KEY,version_id TEXT NOT NULL REFERENCES dataset_version,path TEXT NOT NULL UNIQUE,url TEXT NOT NULL,sha256 TEXT NOT NULL CHECK(length(sha256)=64),bytes INTEGER NOT NULL CHECK(bytes>0),retrieved_at TEXT NOT NULL);
CREATE TABLE department(code TEXT PRIMARY KEY,name TEXT NOT NULL,region TEXT,geometry TEXT NOT NULL,crs TEXT NOT NULL DEFAULT 'EPSG:4326');
CREATE TABLE commune(code TEXT PRIMARY KEY,name TEXT NOT NULL,department TEXT REFERENCES department(code),region TEXT,longitude REAL CHECK(longitude BETWEEN -180 AND 180),latitude REAL CHECK(latitude BETWEEN -90 AND 90),population INTEGER CHECK(population>=0),raw_id TEXT NOT NULL REFERENCES raw_file);
CREATE TABLE postal_code(commune_code TEXT REFERENCES commune(code),postal_code TEXT NOT NULL,PRIMARY KEY(commune_code,postal_code));
CREATE INDEX idx_commune_name ON commune(name);CREATE INDEX idx_commune_department ON commune(department);
CREATE TABLE climate_place(commune_code TEXT PRIMARY KEY REFERENCES commune(code),domain TEXT NOT NULL,reference_start INTEGER NOT NULL,reference_end INTEGER NOT NULL,resolution TEXT NOT NULL,method TEXT NOT NULL,altitude_text TEXT,raw_id TEXT NOT NULL REFERENCES raw_file);
CREATE TABLE scenario(scenario_id TEXT PRIMARY KEY,label TEXT NOT NULL,kind TEXT NOT NULL,description TEXT NOT NULL);
CREATE TABLE climate_model(model_id TEXT PRIMARY KEY,label TEXT NOT NULL,kind TEXT NOT NULL,details TEXT NOT NULL);
CREATE TABLE period(period_id TEXT PRIMARY KEY,label TEXT NOT NULL,start_year INTEGER,end_year INTEGER,kind TEXT NOT NULL,CHECK(end_year>=start_year));
CREATE TABLE indicator(indicator_id TEXT PRIMARY KEY,label TEXT NOT NULL,unit TEXT NOT NULL,definition TEXT NOT NULL,family TEXT NOT NULL,source_url TEXT NOT NULL);
CREATE TABLE climate_value(commune_code TEXT NOT NULL REFERENCES climate_place,indicator_id TEXT NOT NULL REFERENCES indicator,period_id TEXT NOT NULL REFERENCES period,season TEXT NOT NULL,value REAL NOT NULL,lower REAL,upper REAL,scenario_id TEXT NOT NULL REFERENCES scenario,model_id TEXT NOT NULL REFERENCES climate_model,raw_id TEXT NOT NULL REFERENCES raw_file,PRIMARY KEY(commune_code,indicator_id,period_id,season),CHECK(lower IS NULL OR lower<=value),CHECK(upper IS NULL OR value<=upper)) WITHOUT ROWID;
CREATE INDEX idx_climate_comparison ON climate_value(indicator_id,period_id,season);
CREATE TABLE hazard(hazard_id TEXT PRIMARY KEY,label TEXT NOT NULL,category TEXT NOT NULL);
CREATE TABLE commune_hazard(commune_code TEXT NOT NULL REFERENCES commune(code),hazard_id TEXT NOT NULL REFERENCES hazard,raw_id TEXT NOT NULL REFERENCES raw_file,nature TEXT NOT NULL,PRIMARY KEY(commune_code,hazard_id));
CREATE TABLE bibliography(reference_id TEXT PRIMARY KEY,citation TEXT NOT NULL,url TEXT NOT NULL);
CREATE TABLE taxon(taxon_id TEXT PRIMARY KEY,accepted_name TEXT NOT NULL,rank TEXT,phylum TEXT,class_name TEXT,family TEXT);
CREATE TABLE geological_interval(interval_id TEXT PRIMARY KEY,early_name TEXT NOT NULL,late_name TEXT,max_ma REAL NOT NULL,min_ma REAL NOT NULL,CHECK(min_ma>=0 AND max_ma>=min_ma AND max_ma<=4600));
CREATE TABLE fossil_site(site_id INTEGER PRIMARY KEY,name TEXT NOT NULL,longitude REAL NOT NULL CHECK(longitude BETWEEN -180 AND 180),latitude REAL NOT NULL CHECK(latitude BETWEEN -90 AND 90),department TEXT REFERENCES department(code),environment TEXT,coordinate_basis TEXT,coordinate_precision TEXT,geographic_comment TEXT,stratigraphy TEXT,raw_id TEXT NOT NULL REFERENCES raw_file);
CREATE VIRTUAL TABLE fossil_index USING rtree(site_id,min_lon,max_lon,min_lat,max_lat);
CREATE TABLE fossil_occurrence(occurrence_id INTEGER PRIMARY KEY,site_id INTEGER NOT NULL REFERENCES fossil_site,taxon_id TEXT NOT NULL REFERENCES taxon,reference_id TEXT NOT NULL REFERENCES bibliography,interval_id TEXT NOT NULL REFERENCES geological_interval,identified_name TEXT NOT NULL,raw_id TEXT NOT NULL REFERENCES raw_file);
CREATE INDEX idx_occ_site ON fossil_occurrence(site_id);CREATE INDEX idx_occ_taxon ON fossil_occurrence(taxon_id);
CREATE TABLE media(media_id TEXT PRIMARY KEY,category TEXT NOT NULL CHECK(category IN('fossil','organism','place')),page_url TEXT NOT NULL,image_url TEXT NOT NULL,local_path TEXT,author TEXT NOT NULL,license TEXT NOT NULL,caption TEXT NOT NULL,retrieved_at TEXT NOT NULL,association_evidence TEXT NOT NULL);
CREATE TABLE taxon_media(taxon_id TEXT NOT NULL REFERENCES taxon,media_id TEXT NOT NULL REFERENCES media,match_level TEXT NOT NULL CHECK(match_level IN('exact_specimen','same_taxon','same_genus','general')),PRIMARY KEY(taxon_id,media_id));
CREATE TABLE test_place(place_id TEXT PRIMARY KEY,label TEXT NOT NULL,commune_code TEXT REFERENCES commune(code),longitude REAL NOT NULL,latitude REAL NOT NULL,kind TEXT NOT NULL);
CREATE TABLE parcel(parcel_id TEXT PRIMARY KEY,commune_code TEXT REFERENCES commune(code),section TEXT,number TEXT,geometry TEXT NOT NULL,crs TEXT NOT NULL DEFAULT 'EPSG:4326',vintage TEXT,raw_id TEXT NOT NULL REFERENCES raw_file);
CREATE TABLE urban_document(document_id TEXT PRIMARY KEY,label TEXT NOT NULL,type TEXT,approval_date TEXT,publication_date TEXT,url TEXT NOT NULL,status TEXT NOT NULL,raw_id TEXT NOT NULL REFERENCES raw_file);
CREATE TABLE urban_zone(zone_id TEXT PRIMARY KEY,document_id TEXT REFERENCES urban_document,zone_type TEXT,label TEXT,validity_date TEXT,regulation_url TEXT,geometry TEXT NOT NULL,raw_id TEXT NOT NULL REFERENCES raw_file);
CREATE TABLE prescription(prescription_id TEXT PRIMARY KEY,document_id TEXT REFERENCES urban_document,category TEXT,label TEXT,geometry TEXT NOT NULL,raw_id TEXT NOT NULL REFERENCES raw_file);
CREATE TABLE parcel_zone(parcel_id TEXT REFERENCES parcel,zone_id TEXT REFERENCES urban_zone,method TEXT NOT NULL,PRIMARY KEY(parcel_id,zone_id));
CREATE TABLE hazard_zone(zone_id TEXT PRIMARY KEY,hazard_id TEXT REFERENCES hazard,label TEXT NOT NULL,nature TEXT NOT NULL,scenario TEXT,return_period TEXT,geometry TEXT NOT NULL,raw_id TEXT NOT NULL REFERENCES raw_file);
CREATE TABLE spatial_intersection(place_id TEXT REFERENCES test_place,zone_id TEXT REFERENCES hazard_zone,intersects INTEGER NOT NULL CHECK(intersects IN(0,1)),method TEXT NOT NULL,PRIMARY KEY(place_id,zone_id));
CREATE VIEW v_fossils AS SELECT o.*,s.name site_name,s.longitude,s.latitude,s.department,s.coordinate_basis,s.coordinate_precision,t.accepted_name,t.phylum,t.class_name,t.family,i.early_name,i.late_name,i.max_ma,i.min_ma,b.citation,b.url reference_url FROM fossil_occurrence o JOIN fossil_site s USING(site_id) JOIN taxon t USING(taxon_id) JOIN geological_interval i USING(interval_id) JOIN bibliography b USING(reference_id);
CREATE VIEW v_coverage AS SELECT c.code,c.name,c.department,COUNT(DISTINCT v.indicator_id) climate_indicators,COUNT(DISTINCT h.hazard_id) hazard_inventory FROM commune c LEFT JOIN climate_value v ON v.commune_code=c.code AND v.period_id='2050' LEFT JOIN commune_hazard h ON h.commune_code=c.code GROUP BY c.code;
